package provider

import (
	"maps"
	"strings"

	"github.com/google/uuid"
)

// The provider fingerprint seed is generated by the service and retained across
// administrator edits, including edits that disable fingerprinting. Accepting a
// submitted seed would let ordinary Extra input replace the identity used by
// outgoing Codex requests.
//
// Create preparation strips any submitted seed and generates one for a
// recognized enabled mode on an eligible provider. Update preparation first
// retains a valid current seed, then generates one only if the new mode needs
// it and no valid current seed exists. Canonical UUID checking rejects nil,
// alternate encodings, and noncanonical case while accepting surrounding
// whitespace. All preparation helpers copy the top-level map; nested Extra
// values retain their existing ownership.

// CanonicalCodexFingerprintSeed accepts a nonzero UUID string whose trimmed
// text equals its canonical representation. Surrounding whitespace is removed;
// nonstrings, nil UUIDs, alternate encodings, and noncanonical case return
// false.
func CanonicalCodexFingerprintSeed(value any) (string, bool) {
	raw, ok := value.(string)
	if !ok {
		return "", false
	}
	trimmed := strings.TrimSpace(raw)
	parsed, err := uuid.Parse(trimmed)
	if err != nil || parsed == uuid.Nil || trimmed != parsed.String() {
		return "", false
	}
	return trimmed, true
}

// StripCodexFingerprintSeed returns a shallow copy of Extra with the system
// seed key removed. Nil stays nil, while nested values remain shared and
// require caller ownership before later mutation.
func StripCodexFingerprintSeed(extra map[string]any) map[string]any {
	if extra == nil {
		return nil
	}
	stripped := maps.Clone(extra)
	delete(stripped, CodexFingerprintSeedExtraKey)
	return stripped
}

// CodexFingerprintSeed reads and validates the system-managed seed in Extra.
// Missing Extra or a seed that fails CanonicalCodexFingerprintSeed returns
// false, allowing preparation to decide whether generation is needed.
func CodexFingerprintSeed(extra map[string]any) (string, bool) {
	if extra == nil {
		return "", false
	}
	return CanonicalCodexFingerprintSeed(extra[CodexFingerprintSeedExtraKey])
}

// PrepareCodexFingerprintExtraForCreate strips submitted seed input and
// prepares a top-level Extra copy for creation. OpenAI OAuth and Setup Token
// records generate a seed when their mode requires one.
//
// Other platform/type combinations retain the stripped configuration.
// Generation calls the supplied newSeed function once on the eligible path and
// stores its result directly, so the caller supplies a generator that produces
// canonical nonzero UUID text. Nested Extra values remain shared until the
// owning write path copies them.
func PrepareCodexFingerprintExtraForCreate(platform, providerType string, extra map[string]any, newSeed func() string) map[string]any {
	prepared := StripCodexFingerprintSeed(extra)
	if platform != PlatformOpenAI || (providerType != ProviderTypeOAuth && providerType != ProviderTypeSetupToken) || !CodexFingerprintModeRequiresSeed(CodexFingerprintModeFromExtra(prepared)) {
		return prepared
	}
	if prepared == nil {
		prepared = make(map[string]any, 1)
	}
	prepared[CodexFingerprintSeedExtraKey] = newSeed()
	return prepared
}

// PrepareCodexFingerprintExtraForUpdate prepares Extra while keeping an
// eligible provider's current valid seed. Submitted seed text is stripped
// first, and nil or other provider types return that stripped copy.
//
// A valid current seed is retained even when the new configuration disables
// fingerprinting, allowing a later opt-in to reuse the provider identity. With
// no valid current seed, a mode that requires one calls newSeed once and stores
// its result. The generator supplies canonical nonzero UUID text, and the
// prepared map copies top-level entries while nested values remain shared.
func PrepareCodexFingerprintExtraForUpdate(provider *Record, extra map[string]any, newSeed func() string) map[string]any {
	prepared := StripCodexFingerprintSeed(extra)
	if provider == nil || !provider.IsOpenAIOAuthLike() {
		return prepared
	}
	// Retain the service-owned identity even when this update switches the mode
	// off. Re-enabling fingerprinting later then uses the same provider seed.
	if seed, ok := CodexFingerprintSeed(provider.Extra); ok {
		if prepared == nil {
			prepared = make(map[string]any, 1)
		}
		prepared[CodexFingerprintSeedExtraKey] = seed
		return prepared
	}
	if CodexFingerprintModeRequiresSeed(CodexFingerprintModeFromExtra(prepared)) {
		if prepared == nil {
			prepared = make(map[string]any, 1)
		}
		prepared[CodexFingerprintSeedExtraKey] = newSeed()
	}
	return prepared
}

// SanitizedCodexFingerprintExtraUpdates shallow-copies an Extra patch and
// removes submitted seed input. Nil patches remain nil; callers pass the result
// to the storage writer, which owns seed retention or generation.
func SanitizedCodexFingerprintExtraUpdates(updates map[string]any) map[string]any {
	if updates == nil {
		return nil
	}
	sanitized := maps.Clone(updates)
	delete(sanitized, CodexFingerprintSeedExtraKey)
	return sanitized
}
